Hi,
I found that the current inverse softplus is unstable for high-value inputs.
def inv_softplus(x):
    return torch.log(torch.exp(x) - 1)
Probably, the more stable version would be
def inv_softplus(x):
    return x + torch.log(1 - torch.exp(-x))

for example a given example below, how to distinguish which attributes are parameters and which are the backward functions, since both are in init and in forward.


how to freeze the GP parameters, for example the mean or the cov?


class ExactGPModel(gpytorch.models.ExactGP):
    def __init__(self, train_x, train_y, likelihood):
        super(ExactGPModel, self).__init__(train_x, train_y, likelihood)
        self.mean_module = gpytorch.means.ZeroMean()
        matern = gpytorch.kernels.MaternKernel(
            nu=2.5,
            lengthscale_prior=gpytorch.priors.NormalPrior(1, .001)
        )
        self.covar_module = matern

    def forward(self, x):
        mean_x = self.mean_module(x)
        covar_x = self.covar_module(x)
        return gpytorch.distributions.MultivariateNormal(mean_x, covar_x)
